import {paint} from './drawing.js';
import {download} from './backup.js';
function lines(ctx,text,maxWidth){const result=[];for(const paragraph of text.split('\n')){let line='';for(const char of paragraph){if(ctx.measureText(line+char).width>maxWidth&&line){result.push(line);line='';}line+=char;}result.push(line);}return result;}
export async function makeCard(entry){await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=1080;let ctx=canvas.getContext('2d');ctx.font='44px sans-serif';const quoteLines=lines(ctx,entry.quoteSnapshot.text,880);ctx.font='28px sans-serif';const noteLines=lines(ctx,entry.note,880);const drawingHeight=entry.strokes.length?450:0;canvas.height=330+quoteLines.length*72+noteLines.length*46+drawingHeight;ctx=canvas.getContext('2d');ctx.fillStyle='#f5f3eb';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#637165';ctx.font='22px sans-serif';ctx.fillText(`오늘의 한 줄   ·   ${entry.dateKey}`,100,90);let y=185;ctx.fillStyle='#283e33';ctx.font='44px sans-serif';for(const line of quoteLines){ctx.fillText(line,100,y);y+=72;}ctx.font='20px sans-serif';ctx.fillStyle='#637165';ctx.fillText(`${entry.quoteSnapshot.sourceTitle} · 자체 제작 문장`,100,y);y+=70;ctx.font='28px sans-serif';ctx.fillStyle='#283e33';for(const line of noteLines){ctx.fillText(line,100,y);y+=46;}if(drawingHeight){ctx.save();ctx.translate(100,y);paint(ctx,entry.strokes,880,drawingHeight);ctx.restore();}return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('카드를 만들지 못했어요.')),'image/png'));}
export async function exportCard(entry,share=false){const blob=await makeCard(entry);const filename=`오늘의-한-줄-${entry.dateKey}.png`;const file=new File([blob],filename,{type:'image/png'});if(share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'오늘의 한 줄'});return;}catch(error){if(error.name==='AbortError')return;}}download(blob,filename);}
